createStates.source:
function () {
            _super.prototype.execute.call(this);
            this.addPre(game.PreGameStates.HISTORY_LOAD_STATE, game.PreGameStates.LOADING_STATE, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.LOADING_STATE, game.PreGameStates.MAKE_INIT_REQUEST, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.MAKE_INIT_REQUEST, game.PreGameStates.HISTORY_RECOVERY_STATE, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.HISTORY_RECOVERY_STATE, game.PreGameStates.CREATE_GAME, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.CREATE_GAME, game.PreGameStates.RECOVERY_INIT_STATE, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.RECOVERY_INIT_STATE, game.PreGameStates.RECOVERY_LOAD_STATE, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.RECOVERY_LOAD_STATE, game.PreGameStates.BASE_GAME_RECOVERY_STATE, game.SubGames.PRE_GAME);
            this.addPre(game.PreGameStates.BASE_GAME_RECOVERY_STATE, game.BaseGameStates.STOP_REELS_STATE, game.SubGames.BASE_GAME);
            this.addPre(game.PreGameStates.FREE_SPINS_RECOVERY_STATE, game.BonusGameState.FREE_SPIN_REEL_STOP, game.SubGames.FREE_GAME);
            this.addPre(game.PreGameStates.HIDE_PROGRESS_BAR, game.BaseGameStates.IDLE_STATE, game.SubGames.BASE_GAME);
            this.addPre(game.PreGameStates.CREATE_GAME, game.PreGameStates.CREATE_GAME_HELP_STATE, game.SubGames.PRE_GAME);
            this.addBase(game.BaseGameStates.IDLE_STATE, game.BaseGameStates.LOGIC_GLS_STATE, game.SubGames.BASE_GAME);
            this.addBase(game.BaseGameStates.LOGIC_GLS_STATE, game.BaseGameStates.STOP_REELS_STATE, game.SubGames.BASE_GAME);
            this.addBase(game.BaseGameStates.STOP_REELS_STATE, game.BaseGameStates.SHOW_PAYLINE_SPAGHETTI_STATE, game.SubGames.BASE_GAME);
            this.addBase(game.BaseGameStates.SHOW_PAYLINE_SPAGHETTI_STATE, game.BaseGameStates.SHOW_PAYLINE_WINS_STATE, game.SubGames.BASE_GAME);
            this.addBase(game.BaseGameStates.SHOW_PAYLINE_WINS_STATE, game.BaseGameStates.IDLE_STATE, game.SubGames.BASE_GAME);
            this.addBase(game.BaseGameStates.GAME_HELP_STATE, game.BaseGameStates.IDLE_STATE, game.SubGames.BASE_GAME);
            this.addState(game.SubGames.WHEEL_GAME, game.BonusGameState.WHEEL_GAME, game.BonusGameState.WHEEL_GAME_OUTRO, game.SubGames.WHEEL_GAME);
            this.addState(game.SubGames.WHEEL_GAME, game.BonusGameState.WHEEL_GAME_OUTRO, game.BonusGameState.FREE_SPIN_INTRO, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.FREE_SPIN_INTRO, game.BonusGameState.FREE_SPIN_REEL_SPIN, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.FREE_SPIN_REEL_SPIN, game.BonusGameState.FREE_SPIN_REEL_STOP, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.FREE_SPIN_REEL_STOP, game.BonusGameState.FREE_SPIN_RESULT, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.FREE_SPIN_RESULT, game.BonusGameState.FREE_SPIN_OUTRO, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.FREE_SPIN_OUTRO, game.BonusGameState.BONUS_GUARANTEE, game.SubGames.FREE_GAME);
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.BONUS_GUARANTEE, game.BaseGameStates.SHOW_PAYLINE_SPAGHETTI_STATE, game.SubGames.BASE_GAME);
            //max win state..max win is only possible in free spins..
            this.addState(game.SubGames.FREE_GAME, game.BonusGameState.MAX_WIN, game.BaseGameStates.IDLE_STATE, game.SubGames.BASE_GAME);
            // this.addBase(BaseGameStates.END_GLS_STATE,                              BaseGameStates.IDLE_STATE,                  SubGames.BASE_GAME);
            //to do.. this is altered..
            // this._statesModel.init(SubGames.PRE_GAME, PreGameStates.HISTORY_LOAD_STATE);
            this._statesModel.init(game.SubGames.PRE_GAME, game.PreGameStates.HISTORY_LOAD_STATE);
        }

freeNext.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            if (!this._statesModel.isFreeSpin) {
                return;
            }
            var logicResponse = this._server.getLogicResponse();
            var currentFS = logicResponse.freeSpinInfoData.currentFreeSpin;
            var totalFS = logicResponse.freeSpinInfoData.totalFreeSpins;
            if (totalFS - currentFS > 0) {
                if (!this._forceModel.forceOpen) {
                    TweenLite.delayedCall(0.5, function () {
                        _this._statesModel.changeStateByName(game.BonusGameState.FREE_SPIN_REEL_SPIN);
                    });
                }
            }
            else {
                TweenLite.delayedCall(0.5, function () {
                    _this._statesModel.gotoNextState();
                });
            }
        }

startWins.source:
function () {
            _super.prototype.execute.call(this);
            // this._subGamesModel.isWinSkipped = false;
            var logicResponse = this._server.getLogicResponse();
            if (!logicResponse.baseGameRecoverySpinData) {
                //if this is base game..
                this._cyclers.isPreBonusWin = logicResponse.reelSpinData[0].bonusAwarded;
                this._cyclers.stopLineBurstPaylineCycler();
                if (this._statesModel.getCurrentState() === this._statesModel.getStateByName(game.BaseGameStates.SHOW_PAYLINE_WINS_STATE)) {
                    if (logicResponse.reelSpinData[0].bonusAwarded) {
                        this._cyclers.startPreBonusWin(logicResponse, this._server.getInitResponse());
                    }
                    else {
                        this._subGamesModel.isWinPresentationStarted = true;
                        this._cyclers.startPaylinesCycler(logicResponse, this._server.getInitResponse());
                    }
                }
            }
            else {
                //if this is return from free spins.
                this._cyclers.isPreBonusWin = false;
                this._subGamesModel.isWinPresentationStarted = true;
                this._cyclers.stopLineBurstPaylineCycler();
                this._cyclers.startPaylinesCycler(logicResponse, this._server.getInitResponse(), true);
            }
        }

endRequest.source:
function () {
            _super.prototype.execute.call(this);
            if (!this._cyclers.isPreBonusWin && !this._subGamesModel.isEndResponseReceived) {
                this._partnerAdapter.finishedPlay();
                this._partnerAdapter.finishedPostGameAnimations();
                if (!this._historyModel.getIsHistoryReplay()) {
                    this._server.makeEndRequest(new server.GLSRequest([]));
                }
                if (this._autoplayModel.isInProgress()) {
                    this._autoplayModel.updateWinAndStake(this._server.getLogicResponse().gameResultData.totalWin, this._stakesModel.currentBet.totalBet);
                }
            }
        }

playRequest.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [
                this.getStakeEncode(),
                new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
            ];
            if (this._statesModel.getCurrentState().stateName !== game.PreGameStates.RECOVERY_INIT_STATE) {
                var history = this._historyModel.getNextState();
                if (history) {
                    encoders.push(new game.HistoryReplaceEncoder(history));
                }
                if (this._forceModel.forceSet) {
                    if (!this._forceModel.isFreeSpinGaff) {
                        if (this._forceModel.reelData) {
                            var stopPositions = this._forceModel.reelData.positions ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0];
                            var index = this._forceModel.reelData.index ? this._forceModel.reelData.index : 0;
                            var mysterySymbolId = (this._forceModel.reelData.mysterySymbolId != undefined) ? this._forceModel.reelData.mysterySymbolId : -1;
                            var innerWheelId = (this._forceModel.reelData.innerWheelId != undefined) ? this._forceModel.reelData.innerWheelId : -1;
                            var outerWheelId = (this._forceModel.reelData.outerWheelId != undefined) ? this._forceModel.reelData.outerWheelId : -1;
                            var forceEncoder = new game.ForceEncoder(stopPositions, index, mysterySymbolId, innerWheelId, outerWheelId, this._forceModel.reelData.isBonus);
                            encoders.push(forceEncoder);
                        }
                    }
                    else {
                        var fsReelPositions = [];
                        for (var i = 0; i < this._forceModel.fsReelData.length; i++) {
                            fsReelPositions.push(this._forceModel.fsReelData[i].positions);
                        }
                        var fsForceEncoder = new game.FSForceEncoder(fsReelPositions);
                        encoders.push(fsForceEncoder);
                    }
                }
                this._forceModel.reset();
                this._forceModel.forceSet = false;
            }
            if (this._server.getInitResponse().recoveryData.isRecovering == false) {
                this._partnerAdapter.startedPlay();
            }
            var data = new server.GLSRequest(encoders);
            this._server.makeLogicRequest(data);
        }

transitionComplete.source:
function () {
            this._transitionView.removeEventListener(game.TransitionEvent.TRANSITION_COMPLETE, this.onTransitionComplete, this);
            if (this._transitionView.isIntro) {
                this._audioModel.playBonusLoopSound();
                this._gameContextEventDispatcher.dispatchEvent(new game.TransitionEvent(game.TransitionEvent.INTRO_TRANSITION_COMPLETE));
            }
            else {
                this._gameContextEventDispatcher.dispatchEvent(new game.TransitionEvent(game.TransitionEvent.OUTRO_TRANSITION_COMPLETE));
            }
            if (this._transitionView.parent) {
                this._transitionView.parent.removeChild(this._transitionView);
            }
        }

baseBangupComplete.source:
function () {
            var logicResponse = this._serverModel.getLogicResponse();
            var totalWin = logicResponse.baseGameInfoData.totalWagerWin;
            this._totalWin = totalWin;
            this._gameContextEventDispatcher.dispatchEvent(new game.GameEvent(game.GameEvent.WIN_BANGUP_COMPLETE));
            if (this._totalWin > 0) {
                this._audioModel.playBangUpEndOverlaySound();
            }
            //this._audioModel.fadeInBaseGameSound();
        }

baseInfo.source:
function (input, object) {
            var node = input.getElementsByTagName("BGInfo")[0];
            var bgInfoData = new game.BaseGameInfoData;
            bgInfoData.totalWagerWin = parseInt(this.getAttributeFromNode(node, "totalWagerWin", "number"));
            bgInfoData.baseGameWin = parseInt(this.getAttributeFromNode(node, "bgWinnings", "number"));
            bgInfoData.mysterySymbolId = parseInt(this.getAttributeFromNode(node, "mysterySymbol", "number"));
            bgInfoData.isMaxWin = (this.getAttributeFromNode(node, "isMaxWin") === "1");
            bgInfoData.maxWinVal = parseInt(this.getAttributeFromNode(node, "maxWin", "number"));
            object.baseGameInfoData = bgInfoData;
        }

baseAttribute.source:
function (dataNode, attribute, returnType) {
            if (returnType === void 0) { returnType = "string"; }
            var attributeValue = "";
            if (returnType == "number")
                attributeValue = "-1";
            if (dataNode.attributes.getNamedItem(attribute)) {
                attributeValue = dataNode.attributes.getNamedItem(attribute).value;
            }
            return attributeValue;
        }

freeInfo.source:
function (input, object) {
            if (input.getElementsByTagName("FSInfo") && input.getElementsByTagName("FSInfo").length > 0) {
                var node = input.getElementsByTagName("FSInfo")[0];
                var freeSpinInfoData = new game.FreeSpinInfoData;
                freeSpinInfoData.totalFreeSpinWin = parseInt(this.getAttributeFromNode(node, "fsWinnings", "number"));
                freeSpinInfoData.totalFreeSpins = parseInt(this.getAttributeFromNode(node, "freeSpinsTotal", "number"));
                freeSpinInfoData.currentFreeSpin = parseInt(this.getAttributeFromNode(node, "freeSpinNumber", "number"));
                freeSpinInfoData.mysterySymbolId = parseInt(this.getAttributeFromNode(node, "mysterySymbol", "number"));
                freeSpinInfoData.triggerWin = parseInt(this.getAttributeFromNode(node, "scatterWin", "number"));
                freeSpinInfoData.isBonusGuarantee = this.getAttributeFromNode(node, "bonusGuarantee") === "1";
                object.freeSpinInfoData = freeSpinInfoData;
            }
        }

